  const state=hass?.states?.[row.entity],current=row.state==='on'?Date.parse(state?.last_changed):NaN;
  const time=Math.max(...[current,lastOpened.get(row.entity)].filter(value=>Number.isFinite(value)&&value<=Date.now()));
