  const drawing=entry.kind==='person'?'<circle cx="12" cy="6" r="3"/><path d="M6 21v-5a6 6 0 0 1 12 0v5M12 15v6"/>':'<path d="M4 7a10 10 0 0 1 16 0M7 10a6 6 0 0 1 10 0M10 13a2 2 0 0 1 4 0"/><circle cx="12" cy="18" r="2"/>';
