  this.shadowRoot.querySelector('.stage-caption').addEventListener('click',e=>{const id=e.target.closest('button[data-house-view]')?.dataset.houseView;if(id&&this.cameraToggleViews().some(v=>v.id===id))this.selectView(id);});
